sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    response.setContentType('application/json');
    try {
        if (!gs.hasRole('x_2316161_bjit_e_0.employee'))
            throw { status: 403, code: 'forbidden', message: 'You do not have permission to view attendance.' };

        var state = new x_2316161_bjit_e_0.BjitAttendancePunch().getToday();
        response.setStatus(200);
        response.setBody(state);
    } catch (e) {
        if (e && e.status && e.code) {
            response.setStatus(e.status);
            response.setBody({ code: e.code, message: e.message });
        } else {
            gs.error('BJIT attendance today failed: ' + e);
            response.setStatus(500);
            response.setBody({ code: 'attendance_failed', message: 'Attendance could not be loaded. Please try again.' });
        }
    }
})(request, response);
